import type { FormationShape, StudioParams } from '../types/studio';

/**
 * Generates an ASCII Stanford PLY file with vertex positions and RGB colors.
 */
export function buildPLY(
  positions: Float32Array,
  colors: Float32Array,
  count: number,
  maxExportCount = 100000,
): string {
  const actualCount = Math.min(count, maxExportCount, Math.floor(positions.length / 3));
  const lines: string[] = [
    'ply',
    'format ascii 1.0',
    'comment Generated by ParticleStudio',
    `element vertex ${actualCount}`,
    'property float x',
    'property float y',
    'property float z',
    'property uchar red',
    'property uchar green',
    'property uchar blue',
    'end_header',
  ];

  for (let i = 0; i < actualCount; i++) {
    const idx = i * 3;
    const x = positions[idx].toFixed(4);
    const y = positions[idx + 1].toFixed(4);
    const z = positions[idx + 2].toFixed(4);
    const r = Math.max(0, Math.min(255, Math.round((colors[idx] ?? 1) * 255)));
    const g = Math.max(0, Math.min(255, Math.round((colors[idx + 1] ?? 1) * 255)));
    const b = Math.max(0, Math.min(255, Math.round((colors[idx + 2] ?? 1) * 255)));
    lines.push(`${x} ${y} ${z} ${r} ${g} ${b}`);
  }

  return lines.join('\n');
}

/**
 * Generates a Wavefront OBJ file containing `v x y z r g b` vertex data.
 */
export function buildOBJ(
  positions: Float32Array,
  colors: Float32Array,
  count: number,
  maxExportCount = 100000,
): string {
  const actualCount = Math.min(count, maxExportCount, Math.floor(positions.length / 3));
  const lines: string[] = [
    '# Wavefront OBJ Point Cloud',
    '# Generated by ParticleStudio',
    `# Vertices: ${actualCount}`,
    'o ParticleCloud',
  ];

  for (let i = 0; i < actualCount; i++) {
    const idx = i * 3;
    const x = positions[idx].toFixed(4);
    const y = positions[idx + 1].toFixed(4);
    const z = positions[idx + 2].toFixed(4);
    const r = Math.max(0, Math.min(1, colors[idx] ?? 1)).toFixed(3);
    const g = Math.max(0, Math.min(1, colors[idx + 1] ?? 1)).toFixed(3);
    const b = Math.max(0, Math.min(1, colors[idx + 2] ?? 1)).toFixed(3);
    lines.push(`v ${x} ${y} ${z} ${r} ${g} ${b}`);
  }

  return lines.join('\n');
}

function encodeBytesBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(bytes).toString('base64');
  }
  let binary = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

/**
 * Generates a valid GLTF 2.0 JSON document with an embedded base64 POINTS buffer
 * containing POSITION (VEC3) and COLOR_0 (VEC3) vertex attributes.
 */
export function buildGLTF(
  positions: Float32Array,
  colors: Float32Array,
  count: number,
  maxExportCount = 100000,
): string {
  const actualCount = Math.min(count, maxExportCount, Math.floor(positions.length / 3));
  const posByteLen = actualCount * 12;
  const colByteLen = actualCount * 12;
  const totalBytes = posByteLen + colByteLen;
  const buffer = new Uint8Array(totalBytes);
  const view = new DataView(buffer.buffer);

  let minX = Infinity,
    minY = Infinity,
    minZ = Infinity;
  let maxX = -Infinity,
    maxY = -Infinity,
    maxZ = -Infinity;

  for (let i = 0; i < actualCount; i++) {
    const idx = i * 3;
    const x = positions[idx];
    const y = positions[idx + 1];
    const z = positions[idx + 2];

    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (z < minZ) minZ = z;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
    if (z > maxZ) maxZ = z;

    view.setFloat32(i * 12, x, true);
    view.setFloat32(i * 12 + 4, y, true);
    view.setFloat32(i * 12 + 8, z, true);

    const cOffset = posByteLen + i * 12;
    view.setFloat32(cOffset, Math.max(0, Math.min(1, colors[idx] ?? 1)), true);
    view.setFloat32(cOffset + 4, Math.max(0, Math.min(1, colors[idx + 1] ?? 1)), true);
    view.setFloat32(cOffset + 8, Math.max(0, Math.min(1, colors[idx + 2] ?? 1)), true);
  }

  if (actualCount === 0) {
    minX = minY = minZ = 0;
    maxX = maxY = maxZ = 0;
  }

  const base64Uri = `data:application/octet-stream;base64,${encodeBytesBase64(buffer)}`;

  const gltf = {
    asset: {
      version: '2.0',
      generator: 'ParticleStudio Exporter',
    },
    scene: 0,
    scenes: [{ nodes: [0] }],
    nodes: [{ mesh: 0, name: 'ParticleCloud' }],
    meshes: [
      {
        name: 'ParticlePoints',
        primitives: [
          {
            mode: 0, // POINTS
            attributes: {
              POSITION: 0,
              COLOR_0: 1,
            },
          },
        ],
      },
    ],
    buffers: [
      {
        uri: base64Uri,
        byteLength: totalBytes,
      },
    ],
    bufferViews: [
      { buffer: 0, byteOffset: 0, byteLength: posByteLen, target: 34962 },
      { buffer: 0, byteOffset: posByteLen, byteLength: colByteLen, target: 34962 },
    ],
    accessors: [
      {
        bufferView: 0,
        byteOffset: 0,
        componentType: 5126, // FLOAT
        count: actualCount,
        type: 'VEC3',
        min: [minX, minY, minZ],
        max: [maxX, maxY, maxZ],
      },
      {
        bufferView: 1,
        byteOffset: 0,
        componentType: 5126, // FLOAT
        count: actualCount,
        type: 'VEC3',
      },
    ],
  };

  return JSON.stringify(gltf, null, 2);
}

/**
 * Generates a standalone copyable HTML/Three.js embed snippet matching current studio parameters.
 */
export function buildWebGLEmbedSnippet(params: StudioParams, shape: FormationShape): string {
  const accentColor = params.colorStops[params.colorStops.length - 1]?.color ?? '#FF5722';
  const baseColor = params.colorStops[0]?.color ?? '#FFFFFF';
  const count = Math.min(params.particleCount, 120000);

  return `<!-- ParticleStudio Standalone WebGL Embed (${shape.toUpperCase()}) -->
<div id="particle-embed" style="width:100%;height:540px;background:#09090B;overflow:hidden;"></div>
<script type="module">
  import * as THREE from 'https://unpkg.com/three@0.170.0/build/three.module.js';

  const container = document.getElementById('particle-embed');
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#09090B');

  const camera = new THREE.PerspectiveCamera(50, container.clientWidth / container.clientHeight, 1, 2000);
  camera.position.set(0, 60, 380);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  container.appendChild(renderer.domElement);

  const COUNT = ${count};
  const positions = new Float32Array(COUNT * 3);
  const colors = new Float32Array(COUNT * 3);
  const cCore = new THREE.Color('${accentColor}');
  const cOuter = new THREE.Color('${baseColor}');

  for (let i = 0; i < COUNT; i++) {
    const t = i / COUNT;
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    const r = Math.cbrt(Math.random()) * 140;
    positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
    positions[i * 3 + 2] = r * Math.cos(phi);
    const c = cCore.clone().lerp(cOuter, r / 140);
    colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const mat = new THREE.PointsMaterial({
    size: ${params.pointSize.toFixed(1)},
    vertexColors: true,
    transparent: true,
    opacity: 0.88,
    blending: ${params.blendMode === 'additive' ? 'THREE.AdditiveBlending' : 'THREE.NormalBlending'},
    depthWrite: false
  });

  const points = new THREE.Points(geo, mat);
  scene.add(points);

  const clock = new THREE.Clock();
  function animate() {
    requestAnimationFrame(animate);
    const dt = clock.getDelta();
    points.rotation.y += dt * ${Math.max(0.08, params.curlFreq * 0.35).toFixed(2)};
    renderer.render(scene, camera);
  }
  animate();
</script>`;
}
